#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <arpa/inet.h>

#define MAX_POOL_SIZE 16
#define DNS_RESPONSE_BUF 512
#define CONN_TYPE_TCP 0x01
#define CONN_TYPE_UDP 0x02

typedef struct {
    int fd;
    uint8_t conn_type;
    uint32_t refcount;
    void *protocol_state;
} pool_entry_t;

typedef struct {
    uint16_t txn_id;
    uint16_t flags;
    uint16_t qdcount;
    uint16_t ancount;
    uint16_t nscount;
    uint16_t arcount;
} dns_header_t;

typedef struct {
    uint8_t *raw_data;
    size_t data_len;
    uint32_t ttl;
    uint16_t rtype;
    uint16_t rclass;
} dns_rr_t;

typedef struct {
    int socket_fd;
    uint16_t msg_len;
    uint8_t pending_bytes;
    uint8_t state;
} tcp_state_t;

typedef struct {
    int socket_fd;
    uint8_t retries;
    uint8_t state;
} udp_state_t;

static pool_entry_t connection_pool[MAX_POOL_SIZE];
static int pool_count = 0;

pool_entry_t *pool_acquire(uint8_t type) {
    for (int i = 0; i < pool_count; i++) {
        if (connection_pool[i].conn_type == type && connection_pool[i].refcount == 0) {
            connection_pool[i].refcount++;
            return &connection_pool[i];
        }
    }
    if (pool_count >= MAX_POOL_SIZE) return NULL;
    pool_entry_t *entry = &connection_pool[pool_count];
    entry->conn_type = type;
    entry->refcount = 1;
    entry->fd = (pool_count + 1) + 100;
    if (type == CONN_TYPE_TCP) {
        tcp_state_t *ts = (tcp_state_t *)calloc(1, sizeof(tcp_state_t));
        if (!ts) return NULL;
        ts->socket_fd = entry->fd;
        ts->state = 1;
        entry->protocol_state = ts;
    } else {
        udp_state_t *us = (udp_state_t *)calloc(1, sizeof(udp_state_t));
        if (!us) return NULL;
        us->socket_fd = entry->fd;
        us->state = 1;
        entry->protocol_state = us;
    }
    pool_count++;
    return entry;
}

void pool_release(pool_entry_t *entry) {
    if (entry && entry->refcount > 0) {
        entry->refcount--;
    }
}

static pool_entry_t *promote_connection(pool_entry_t *old_entry) {
    /* Create a NEW TCP connection instead of mutating the existing entry */
    pool_entry_t *new_entry = pool_acquire(CONN_TYPE_TCP);
    if (!new_entry) return NULL;
    /* Release the old UDP entry so it can be reused cleanly */
    pool_release(old_entry);
    return new_entry;
}

static int parse_dns_response(uint8_t *buf, size_t len, pool_entry_t *conn, dns_rr_t *out) {
    if (len < sizeof(dns_header_t)) return -1;
    dns_header_t *hdr = (dns_header_t *)buf;
    uint16_t flags = ntohs(hdr->flags);
    uint16_t ancount = ntohs(hdr->ancount);
    int truncated = (flags >> 9) & 1;

    if (truncated && conn->conn_type == CONN_TYPE_UDP) {
        return 1; /* signal retry needed - caller handles promotion */
    }

    if (ancount == 0) return -1;

    size_t offset = sizeof(dns_header_t);
    /* skip question section */
    while (offset < len && buf[offset] != 0) {
        if ((buf[offset] & 0xC0) == 0xC0) { offset += 2; break; }
        uint8_t label_len = buf[offset];
        if (offset + label_len + 1 > len) return -1;
        offset += label_len + 1;
    }
    if (offset < len && buf[offset] == 0) offset++;
    offset += 4; /* qtype + qclass */

    /* parse first answer */
    if (offset + 12 > len) return -1;
    if ((buf[offset] & 0xC0) == 0xC0) offset += 2;
    else { while (offset < len && buf[offset] != 0) { offset += buf[offset] + 1; } offset++; }

    if (offset + 10 > len) return -1;
    out->rtype = ntohs(*(uint16_t *)(buf + offset)); offset += 2;
    out->rclass = ntohs(*(uint16_t *)(buf + offset)); offset += 2;
    out->ttl = ntohl(*(uint32_t *)(buf + offset)); offset += 4;
    uint16_t rdlength = ntohs(*(uint16_t *)(buf + offset)); offset += 2;

    if (offset + rdlength > len) return -1;
    out->raw_data = buf + offset;
    out->data_len = rdlength;
    return 0;
}

int resolve_and_cache(const char *hostname, uint8_t *response_buf, size_t resp_len) {
    pool_entry_t *conn = pool_acquire(CONN_TYPE_UDP);
    if (!conn) return -1;

    dns_rr_t record;
    memset(&record, 0, sizeof(record));
    int result = parse_dns_response(response_buf, resp_len, conn, &record);

    if (result == 1) {
        /* Promote by acquiring a new TCP connection, releasing old */
        pool_entry_t *tcp_conn = promote_connection(conn);
        if (!tcp_conn) { return -1; }
        conn = tcp_conn;
        tcp_state_t *tcp = (tcp_state_t *)conn->protocol_state;
        tcp->msg_len = (uint16_t)resp_len;
        result = parse_dns_response(response_buf, resp_len, conn, &record);
    }

    if (result == 0 && record.data_len == 4 && record.rtype == 1) {
        char ip_str[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, record.raw_data, ip_str, sizeof(ip_str));
        printf("Resolved %s -> %s (TTL: %u)\n", hostname, ip_str, record.ttl);
    }

    pool_release(conn);
    return result;
}

int handle_concurrent_query(const char *name1, const char *name2,
                            uint8_t *buf1, size_t len1,
                            uint8_t *buf2, size_t len2) {
    pool_entry_t *conn1 = pool_acquire(CONN_TYPE_UDP);
    pool_entry_t *conn2 = pool_acquire(CONN_TYPE_UDP);
    if (!conn1 || !conn2) { pool_release(conn1); pool_release(conn2); return -1; }

    dns_rr_t r1, r2;
    memset(&r1, 0, sizeof(r1));
    memset(&r2, 0, sizeof(r2));

    int res1 = parse_dns_response(buf1, len1, conn1, &r1);
    int res2 = parse_dns_response(buf2, len2, conn2, &r2);

    if (res1 == 1) {
        /* Safely promote conn1 without affecting conn2 */
        pool_entry_t *tcp_conn = promote_connection(conn1);
        if (tcp_conn) {
            conn1 = tcp_conn;
            res1 = parse_dns_response(buf1, len1, conn1, &r1);
        }
    }

    pool_release(conn1);
    pool_release(conn2);
    return (res1 == 0 && res2 == 0) ? 0 : -1;
}

int main(int argc, char **argv) {
    uint8_t test_response[] = {
        0x00, 0x01, 0x82, 0x00, 0x00, 0x01, 0x00, 0x01,
        0x00, 0x00, 0x00, 0x00, 0x07, 0x65, 0x78, 0x61,
        0x6d, 0x70, 0x6c, 0x65, 0x03, 0x63, 0x6f, 0x6d,
        0x00, 0x00, 0x01, 0x00, 0x01, 0xc0, 0x0c, 0x00,
        0x01, 0x00, 0x01, 0x00, 0x00, 0x0e, 0x10, 0x00,
        0x04, 0x5d, 0xb8, 0xd8, 0x22
    };
    resolve_and_cache("example.com", test_response, sizeof(test_response));
    return 0;
}
